anilist.co/file/anilistcdn/character/large/b401113-a4ZAr6BT0J9C.png"}},"voiceActors":[{"name":{"full":"Hiroshi Yanaka"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/staff/large/n95477-zUeFZNtjTgap.png"}}]},{"node":{"id":391467,"name":{"full":"Kengo Kuga"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/character/large/b391467-OuxtIBijSPC6.png"}},"voiceActors":[{"name":{"full":"Shunsuke Takeuchi"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/staff/large/n119185-65kkxuTRxAgo.png"}}]},{"node":{"id":401114,"name":{"full":"Bunshichi Yagura"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/character/large/b401114-XUb8zlsTBKcU.png"}},"voiceActors":[{"name":{"full":"Daichi Endou"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/staff/large/n105675-XnR4PwkkKbRH.jpg"}}]},{"node":{"id":391468,"name":{"full":"Noriko Momokawa"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/character/large/b391468-9mUnTEBy4lZn.png"}},"voiceActors":[{"name":{"full":"Minako Kotobuki"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/staff/large/n101634-IiPW117K0ybp.png"}}]},{"node":{"id":401115,"name":{"full":"Naeko Momokawa"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/character/large/default.jpg"}},"voiceActors":[{"name":{"full":"Mayumi Asano"},"image":{"large":"https://s4.anilist.co/file/anilistcdn/staff/large/n95400-BUUDA2OwVREh.png"}}]}]},"coverImage":{"color":"#fec950","large":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/medium/bx103303-IF43hFJPPv2Y.png","extraLarge":"https://s4.anilist.co/file/anilistcdn/media/anime/cover/large/bx103303-IF43hFJPPv2Y.png"},"popularity":40186,"bannerImage":"https://s4.anilist.co/file/anilistcdn/media/anime/banner/103303-K73aVOqkCPqL.jpg","description":"The novel takes place in the summer of 1907, the 40th year of the Meiji era. 15-year-old Inako Momokawa lives in the Fushimi area of Kyoto, and is the second daughter of a sake brewer. Nothing she does ever comes out right, and she receives a scolding from her father every day. Her only relief is the trust she places in her prayers to the gods. One day while at Fushimi Inari shrine, she meets a freewheeling young man named Kihachi Sakamoto. He rejects the gods, and boasts of the incoming age of electricity. <br><br>

The topic of marriage suddenly comes up in Inako's household. Her father is one-sidedly making all the decisions for her, and Inako is about to give up hope. It is then that Kihachi draws out Inako's true feelings of wanting to run away from her family. The only way to stop her marriage is to find an unusual book called the "Electricity Catalog." The book is a prediction book about electricity that Kihachi wrote when he was a child, but his older brother Seiroku took the book, and its current whereabouts are unknown. Inako and Kihachi together go in search of the book across Kyoto and Shiga prefectures.<br><br>

